template <typename T>
class OptimizedReverseIterator {
    T* p;
public:
    explicit OptimizedReverseIterator(T* ptr) : p(ptr) {}

    // Indirection: Accesses element *before* current base pointer
    T& operator*() const { return p[-1]; }

    // Traversal: Reverse increment maps to base decrement (p--),
    // crucial for efficient hardware prefetching.
    OptimizedReverseIterator& operator++() {
        --p;
        return *this;
    }

    // Comparison flip: it1 < it2 translates to base(it1) > base(it2).
    // Compiler must handle boundary conditions (e.g., end() points to begin()).
    bool operator<(const OptimizedReverseIterator& other) const {
        return p > other.p;
    }

    bool operator==(const OptimizedReverseIterator& other) const {
        return p == other.p;
    }
};
